INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18101, 'Jeremiah 10:13', 'Jeremiah', 10, 13, '&nbsp;کله چې هغه برېښنا ته حُکم وکړى نو په آسمان کښې وريځې په غرار شى، هغه وريځې د زمکې د يو سر نه تر بل سره پورې خوروى. هغه برېښنا د باران سره رالېږى او د خپلو ذخيرو نه هوا رالوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18102, 'Jeremiah 10:14', 'Jeremiah', 10, 14, '&nbsp;د انسان ټول نسلونه بې‌عقله او بې‌علمه دى، هغه کاريګر چې بُتان جوړوى دوئ به د دې بُتانو په وجه وشرميږى، ځکه چې د دوئ بُتان هم دوکه ده او ساه په کښې نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18103, 'Jeremiah 10:15', 'Jeremiah', 10, 15, '&nbsp;دا بُتان فضول او سپک څيز دے. د حساب کِتاب په ورځ به دا ټول تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18104, 'Jeremiah 10:16', 'Jeremiah', 10, 16, '&nbsp;خو د بنى اِسرائيلو خُدائ د بُت په شان نۀ دے. هغه د هر شى خالق دے، د بنى اِسرائيلو په شمول چې د هغۀ خپل خلق دى. او د هغۀ نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18105, 'Jeremiah 10:17', 'Jeremiah', 10, 17, '&nbsp;اے محاصره شوې ښاريې. تاسو خپله کډه راوچته کړئ، دشمنانو درنه ګېره اچولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18106, 'Jeremiah 10:18', 'Jeremiah', 10, 18, '&nbsp;ځکه مالِک خُدائ داسې فرمائى چې، ”ناګهانه به دا ځل د دې مُلک اوسېدونکى بهر وغورزوم. زۀ به په تاسو لوئ مصيبت نازل کړم، او په آخر کښې به تاسو ته زما د غصې پته ولګى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18107, 'Jeremiah 10:19', 'Jeremiah', 10, 19, '&nbsp;واى واى، تباه شوم، زما زخمونه سخت دى، زما بيمارى د رغېدو نه بهر ده، چې ضرور دا برداشت کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18108, 'Jeremiah 10:20', 'Jeremiah', 10, 20, '&nbsp;بلکې زمونږ خېمې تباه شوې دى او پړى يې شلېدلى دى، زما ماشومان ما نه اخستے شوى دى. يو هم نۀ دے پاتې شوے، ټول بوتلے شوى دى زۀ به يې دوباره ونۀ وينم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18109, 'Jeremiah 10:21', 'Jeremiah', 10, 21, '&nbsp;زما د قوم شپونکى بې‌شعوره او بې‌عقله شوى دى. دوئ نور د مالِک خُدائ سره مشوره نۀ کوى. نو په دې وجه دوئ پوره ناکاميابه شوى دى، او د دوئ ټولې رمې دانه وانه شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18110, 'Jeremiah 10:22', 'Jeremiah', 10, 22, '&nbsp;غوږ ونيسئ، د شمال د خوا نه د غټ لښکر د راتلو يروونکے شور اورېدے کيږى. د يهوداه ښارونه به تباه او برباد شى او د ګيدړانو غار به ترې نه جوړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18111, 'Jeremiah 10:23', 'Jeremiah', 10, 23, '&nbsp;اے مالِکه خُدايه، زۀ په دې پوهېږم چې د انسان د ژوندون اختيار د دۀ په خپل لاس کښې نۀ دے. او نۀ هغه په خپلې مرضۍ سره د خپل ژوند لار مقررولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18112, 'Jeremiah 10:24', 'Jeremiah', 10, 24, '&nbsp;اے مالِکه خُدايه، په نرمۍ سره زما اصلاح وکړه، او په خپل قهر او غضب کښې دې زما اصلاح مۀ کوه ګنې زۀ به د دُنيا نه ورک شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18113, 'Jeremiah 10:25', 'Jeremiah', 10, 25, '&nbsp;څوک چې تا نۀ پېژنى خپل قهر و غضب دې په هغه خلقو نازل کړه، او په هغه چا څوک چې ستا نوم په خولۀ نۀ اخلى، ځکه چې ستا قوم بنى اِسرائيل يې وژلى دى، او هغوئ دوئ لواړ تېر کړى او تباه کړى يې دى، او مُلک يې ورله وران ويجاړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18114, 'Jeremiah 11:1', 'Jeremiah', 11, 1, '&nbsp;مالِک خُدائ يرمياه ته دا پېغام ورکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18115, 'Jeremiah 11:2', 'Jeremiah', 11, 2, '&nbsp;”تاسو د دې لوظ شرطونو ته غوږ ونيسئ او هغه د يروشلم او يهوداه خلقو ته ووايه کوم چې ما تاسو سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18116, 'Jeremiah 11:3', 'Jeremiah', 11, 3, '&nbsp;هغوئ ته ووايه چې دا هغه موضوع ده چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک فرمائى، لعنت دې وى په هر هغه چا چې د دې لوظ د شرطونو پيروى نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18117, 'Jeremiah 11:4', 'Jeremiah', 11, 4, '&nbsp;دا هغه لوظ دے چې کله ما ستاسو پلار نيکۀ سره په هغه وخت کښې کړے دے کله چې ما هغوئ د مِصر نه بهر راوويستل د هغه ځائ نه چې لکه د اور د بټۍ په شان وو. کۀ چرې تاسو زما د حکمونو پيروى وکړئ کوم چې ما تاسو له درکړى دى، نو بيا به تاسو زما قوم يئ، او زۀ به ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18118, 'Jeremiah 11:5', 'Jeremiah', 11, 5, '&nbsp;نو زۀ به بيا خپل هغه لوظ پوره کړم کوم چې ما ستاسو د پلار نيکۀ سره کړے وو چې زۀ به هغوئ له هغه زمکه ورکړم چې په کښې د شهد او پئ ډېر تېر دى او په کوم کښې چې تاسو نن اوسېږئ.“ نو بيا ما جواب ورکړو چې، ”آمين، مالِکه خُدايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18119, 'Jeremiah 11:6', 'Jeremiah', 11, 6, '&nbsp;بيا مالِک خُدائ ما ته وفرمائيل، ”لاړ شه او د يهوداه په ښارونو او د يروشلم په کوڅو کښې وګرځه. هلته زما ټول پېغامونه هغوئ ته بيان کړه او خلقو ته ووايه چې، د لوظ په شرطونو باندې غور وکړئ، او په هغۀ باندې عمل وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18120, 'Jeremiah 11:7', 'Jeremiah', 11, 7, '&nbsp;کله چې ما ستاسو پلار نيکۀ د مِصر نه بهر راويستل نو ما بار بار دوئ ته خبردارے ورکړو چې زما تابعدارى وکړئ او تر نن ورځ پورې لګيا يم او هم دا خبردارے ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18121, 'Jeremiah 11:8', 'Jeremiah', 11, 8, '&nbsp;بلکې هغوئ نۀ ما ته غوږ ونيولو او نۀ يې زما په خبرو غور وکړلو خو په ځائ د دې هغوئ هر يو د خپل سرکشه زړۀ د خواهشاتو په مطابق ژوند تېرولو. او زما د لوظ د احکامو پيروى يې ونۀ کړه، نو بيا ما هم په هغوئ هغه ټول لعنتونه نازل کړل چې په لوظ کښې يې ذکر شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18122, 'Jeremiah 11:9', 'Jeremiah', 11, 9, '&nbsp;نو دوباره بيا مالِک خُدائ ما ته وفرمائيل چې، ”د يهوداه او د يروشلم خلقو زما خِلاف سازش جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18123, 'Jeremiah 11:10', 'Jeremiah', 11, 10, '&nbsp;هغوئ د خپل پلار نيکۀ پخوانى د ګناهونو لارو ته رجوع کړې ده، د هغوئ پلار نيکۀ زما کلام ته غوږ نۀ نيولو او د نورو معبودانو پيروى او عبادت يې شروع کړو. دواړو اِسرائيل او يهوداه هغه لوظ مات کړو کوم چې ما د دوئ پلار نيکۀ سره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18124, 'Jeremiah 11:11', 'Jeremiah', 11, 11, '&nbsp;نو د دې دپاره زۀ مالِک خُدائ دا وايم چې، زۀ به په دوئ هغه افتونه او مصيبتونه راولم چې دوئ به ترې نه تښتېدلے نۀ شى. کۀ څۀ هم چې دوئ ما ته د مدد دپاره وژاړى او چغې ووهى، خو زۀ به يې نۀ اورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18125, 'Jeremiah 11:12', 'Jeremiah', 11, 12, '&nbsp;نو د يهوداه او د يروشلم خلق به معبودانو له لاړ شى او فرياد به ورته وکړى، چا ته چې هغوئ خوشبويۍ سوزولې. خو هرکله چې افت په دوئ باندې راشى نو په هغه وخت کښې به هغه بُتان دوئ بچ نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18126, 'Jeremiah 11:13', 'Jeremiah', 11, 13, '&nbsp;اے د يهوداه خلقو وګورئ ستاسو د خپلو ښارونو په تعداد کښې معبودان دى، او د يروشلم د کوڅو په تعداد کښې تاسو شرمناکې ډيرې قربان‌ګاه جوړې کړې دى، چې په کښې د بعل بُت دپاره د خوشبو سوزولو قربانۍ پېش کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18127, 'Jeremiah 11:14', 'Jeremiah', 11, 14, '&nbsp;اے يرمياه، تۀ د دې خلقو دپاره نۀ ما ته دُعا او نۀ مِنت زارى وکړې، ځکه چې زۀ به دوئ ته په هغه وخت کښې چې کله په تکليف کښې وى غوږ نۀ نيسم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18128, 'Jeremiah 11:15', 'Jeremiah', 11, 15, '&nbsp;نو بيا تاسو زما کور ته د داخلېدو څۀ حق لرئ چې تاسو بد کارونه وکړل، اے زما محبوب قومه؟ آيا ستاسو د نذرانې او د قربانۍ مقدسې غوښې پېش کول به تاسو د تباهۍ نه بچ کړى څۀ؟ او په حقيقت کښې تاسو په بدعملۍ کولو کښې خوشحاله يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18129, 'Jeremiah 11:16', 'Jeremiah', 11, 16, '&nbsp;ما مالِک خُدائ به په يو وخت کښې تاسو ته د زيتُونو د شنې او ښکلې ونې لقب درکړے وو چې د ښو مېوو نه ډکې وى. خو د سخت او زورَور طوفان په شور کښې به زۀ ستا په پاڼو اور بل کړم، او ستا څانګې به ماتې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18130, 'Jeremiah 11:17', 'Jeremiah', 11, 17, '&nbsp;ما، مالِک خُدائ ربُ الافواج اِسرائيل او يهوداه د ونې په شان کَرلى وُو، خو اوس مې په تاسو د افت راوستلو فېصله وکړه. ځکه چې تاسو بدعملى وکړه، او د بعل بُت ته د خوشبويۍ په سوزولو تاسو زما غصه راوپاروله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18131, 'Jeremiah 11:18', 'Jeremiah', 11, 18, '&nbsp;نو بيا مالِک خُدائ زۀ د هغوئ د بدو منصوبو نه خبر کړم کومې چې دشمنانو زما خِلاف جوړې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18132, 'Jeremiah 11:19', 'Jeremiah', 11, 19, '&nbsp;زۀ د هغه بې‌ګناه ګډُورى په شان وم چې د حلالولو دپاره روان کړے شوے وى او ما ته زما خِلاف د هغوئ د بدو منصوبو عِلم نۀ وو. هغوئ وئيل، ”راځئ چې د مېوې هغه ډکه ونه راوغورزوُو، راځئ چې هغه د ژوندو د دُنيا نه ختم کړُو چې نور د هغۀ نوم د دُنيا نه د تل دپاره ورک شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18133, 'Jeremiah 11:20', 'Jeremiah', 11, 20, '&nbsp;نو بيا ما سوال وکړو چې، ”اے مالِکه خُدايه ربُ الافواجه. تۀ عادل او اِنصاف کوونکے يې، تا ته د هغوئ د زړُونو او سوچونو پته ده، زۀ غواړم چې تۀ زما بدله واخلې او هغه په خپله ووينم، نو اوس ما خپله فېصله تا ته پرېښې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18134, 'Jeremiah 11:21', 'Jeremiah', 11, 21, '&nbsp;مالِک خُدائ فرمائى، ”د عنتوت خلق غواړى چې تا ووژنى. هغوئ وائى چې تۀ د مالِک خُدائ په نوم نبوت مۀ کوه ګنې تا به مړ کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18135, 'Jeremiah 11:22', 'Jeremiah', 11, 22, '&nbsp;نو مالِک خُدائ ربُ الافواج د دوئ په حقله فرمائى، زۀ به هغوئ له سزا ورکړم. د هغوئ ځوانان به په جنګ کښې ووژلے شى، او د هغوئ زامن او لوڼه به د قحط په وجه مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18136, 'Jeremiah 11:23', 'Jeremiah', 11, 23, '&nbsp;د هغوئ نه به يو هم بچ پاتې نۀ شى ځکه چې زۀ به د عنتوت په خلقو افت رانازل کړم. کله چې د هغوئ د سزا وخت راورسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18137, 'Jeremiah 12:1', 'Jeremiah', 12, 1, '&nbsp;اے مالِکه خُدايه، تۀ همېشه ما سره اِنصاف کوې کله چې زۀ يوه مسئله ستا په حضور کښې وړاندې کړم. نو ما ته د مقدمې کولو اجازت راکړه، نو دا بدکاران ولې دومره ترقى کوى؟ او ولې ټول غداران دومره په آرام ژوند تېروى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18138, 'Jeremiah 12:2', 'Jeremiah', 12, 2, '&nbsp;تا هغوئ کَرلى دى او دوئ جرړې کړې دى، دا لوئ شى او مېوه ونيسى. تۀ هر وخت د هغوئ په خولۀ يې، خو د هغوئ د زړونو نه لرې يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18139, 'Jeremiah 12:3', 'Jeremiah', 12, 3, '&nbsp;خو اے مالِکه خُدايه، تۀ ما پېژنې، او تۀ ما وينې او تۀ په ما آزمېښت وکړه چې زۀ ستا يم. دا بدعمله خلق داسې راکاږه لکه څنګه چې يو ګډ د حلالولو دپاره راښکلے شى، او د حلالولو پورې يې يوې خوا ته وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18140, 'Jeremiah 12:4', 'Jeremiah', 12, 4, '&nbsp;دا زمکه به تر کومې پورې ماتم کوى او په پټو کښې به يې ګياه اوچيږى؟ څوک چې په دې مُلک کښې اوسيږى نو د هغوئ د بدعملۍ په وجه مارغان او ځناور تباه شوى دى، او هم په دې وجه خلق دا وائى چې، ”خُدائ به هم حيران وى چې مونږ سره به څۀ کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18141, 'Jeremiah 12:5', 'Jeremiah', 12, 5, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”اے يرمياه، کۀ چرې تۀ د انسانانو سره په منډه وهلو دومره ستړے کېږې، نو تۀ به د آسونو سره څۀ مقابله وکړې؟ کۀ چرې تۀ په يو هوار او محفوظه مېدان کښې تيندکونه خورې او راغورزېږې، نو تۀ به د اُردن سره په ګڼ ځنګل کښې څۀ کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18142, 'Jeremiah 12:6', 'Jeremiah', 12, 6, '&nbsp;تر دې چې ستا وروڼه، او ستا د خپل خاندان خلق ستا مخالفت کوى. هغوئ ستا خلاف شکايتونه کوى. په هغوئ باور مۀ کوه، کۀ څۀ هم چې هغوئ ستا ښۀ وائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18143, 'Jeremiah 12:7', 'Jeremiah', 12, 7, '&nbsp;مالِک خُدائ فرمائى، ”ما خپل خلق پرېښودل، چې زما خاص ميراث دے. ما ته ډېر ګران خلق مې د دشمنانو لاسونو ته حواله کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18144, 'Jeremiah 12:8', 'Jeremiah', 12, 8, '&nbsp;زما غوره شوے قوم لکه د ځنګل د زمرى په شان ما ته وغړمبېدو، نو په دې وجه زۀ د هغوئ نه نفرت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18145, 'Jeremiah 12:9', 'Jeremiah', 12, 9, '&nbsp;آيا دا مُلک د ګيدړانو غار دے چې ټپوسان پرې بره الوځى رالوځى. خو ځنګلى ځناور دې راشى چې د هغوئ لاشونه وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18146, 'Jeremiah 12:10', 'Jeremiah', 12, 10, '&nbsp;ډېرو حاکمانو زما د انګورو باغونه برباد کړى دى، او هغوئ ټول بوټى د پښو لاندې کړى دى او ښائست يې ورله ختم او په بيابان بدل کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18147, 'Jeremiah 12:11', 'Jeremiah', 12, 11, '&nbsp;هغوئ د دې نه تش بيابان جوړ کړے دے او ما د خپلو خلقو د ماتم ژړا اورېدلې ده، او زما د ټول مُلک نه دشته بيابان جوړ شوے دے، او څوک يې هم پرواه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18148, 'Jeremiah 12:12', 'Jeremiah', 12, 12, '&nbsp;د بيابان په ټولو اوچتو او خُشکو غونډو د قتل و غارت فوج ليدلے کيږى، ځکه چې د مالِک خُدائ تُوره به د يو سر نه تر بل سره پورې هغوئ هلاک کړى. نو څوک به هم محفوظ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18149, 'Jeremiah 12:13', 'Jeremiah', 12, 13, '&nbsp;زما خلقو غنم وکَرل، خو تش ازغى يې ورېبل، هغوئ ډېر محنت وکړو خو هيڅ فائده يې حاصله نۀ کړه. ځکه د مالِک خُدائ د سختې غصې په وجه، هغوئ صرف د رُسوايۍ او شرم فصل ورېبلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18150, 'Jeremiah 12:14', 'Jeremiah', 12, 14, '&nbsp;مالِک خُدائ فرمائى، ”زۀ به د بنى اِسرائيلو نه هغه ټول شريره او بدکاره ګاونډيان د جرړې نه راوکاږم څوک چې د هغوئ په زمکه قبضه کول غواړى، او زۀ به يهوداه هم د بنى اِسرائيلو د مينځ نه راوکاږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18151, 'Jeremiah 12:15', 'Jeremiah', 12, 15, '&nbsp;خو کله چې زۀ هغوئ راوباسم، نو بيا به زۀ په هغوئ باندې رحم وکړم، او زۀ به هغوئ هر يو قوم خپل ميراث او خپل مُلک ته واپس راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18152, 'Jeremiah 12:16', 'Jeremiah', 12, 16, '&nbsp;او بيا کۀ چرې دا قومونه په رښتيا سره زما د خلقو طريقې زده کړى، او کۀ هغوئ زما په نوم قسم خوړل زده کړى او وائى چې په يقين سره مالِک خُدائ ژوندے دے، لکه څنګه چې هغوئ يو وخت زما قوم ته د بعل د بُت په نوم قسم خوړل ور زده کړى وُو، نو هغوئ به بيا زما د قوم په مينځ کښې آباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18153, 'Jeremiah 12:17', 'Jeremiah', 12, 17, '&nbsp;خو کۀ چرې هر يو قوم زما خبرو ته غوږ ونۀ نيسى، نو بيا به زۀ هغه قوم په مکمل توګه د بېخ نه راوکاږم او نيست و نابود به يې کړم.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18154, 'Jeremiah 13:1', 'Jeremiah', 13, 1, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”لاړ شه او د خپل ځان دپاره د کتان لنګ واخله او د ملا نه يې تاؤ کړه خو چې په اوبو کښې درنه لوند نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18155, 'Jeremiah 13:2', 'Jeremiah', 13, 2, '&nbsp;نو د مالِک خُدائ د هدايت په مطابق ما لنګ واخستو او د ملا نه مې تاؤ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18156, 'Jeremiah 13:3', 'Jeremiah', 13, 3, '&nbsp;نو بيا په دوېم ځل د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18157, 'Jeremiah 13:4', 'Jeremiah', 13, 4, '&nbsp;”کوم لنګ چې تا اخستے او تاؤ کړے دے اوس د فرات سيند ته لاړ شه او هلته د ګټ په سورى کښې يې پټ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18158, 'Jeremiah 13:5', 'Jeremiah', 13, 5, '&nbsp;نو د مالِک خُدائ د هدايت په مطابق زۀ لاړم او لنګ مې هلته پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18159, 'Jeremiah 13:6', 'Jeremiah', 13, 6, '&nbsp;څۀ موده وروستو بيا مالِک خُدائ ما ته وفرمائيل، ”د فرات سيند ته لاړ شه او هغه لنګ بيا راواخله کوم چې ما درته فرمائيلى وُو چې هلته يې پټ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18160, 'Jeremiah 13:7', 'Jeremiah', 13, 7, '&nbsp;نو بيا زۀ لاړم او هغه ځائ نه مې راوويستو په کوم ځائ کښې چې ما لنګ پټ کړے وو، خو ومې ليدو چې دا بلکل سخا شوے وو او د هيڅ کار نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18161, 'Jeremiah 13:8', 'Jeremiah', 13, 8, '&nbsp;نو د مالِک خُدائ کلام بيا په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18162, 'Jeremiah 13:9', 'Jeremiah', 13, 9, '&nbsp;”لکه څنګه چې دا لنګ سخا شوے دے دغه رنګ به زۀ د يهوداه او د يروشلم لوئ غرور سخا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18163, 'Jeremiah 13:10', 'Jeremiah', 13, 10, '&nbsp;دې بدکاره خلقو چا چې زما د کلام د اورېدو نه اِنکار وکړو، او د خپلو سرکشه زړونو يې ومنل او د نورو معبودانو عبادت او خِدمت يې شروع کړو، نو د هغوئ حالت به د دې سخا شوے لنګ په شان وى چې د هيڅ کار نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18164, 'Jeremiah 13:11', 'Jeremiah', 13, 11, '&nbsp;لکه څنګه چې لنګ د انسان د ملا نه کلک تاو وى، نو دغه شان ما د اِسرائيل او د يهوداه خلق خپل ځان سره وتړل چې دوئ زما د نوم د شُهرت، تعريف او عزت باعث وى. خو هغوئ زما تابعدارى ونۀ کړه.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18165, 'Jeremiah 13:12', 'Jeremiah', 13, 12, '&nbsp;نو هغوئ ته ووايه چې، مالِک خُدائ د بنى اِسرائيلو خُدائ پاک فرمائى، ”ستا د ميو ټولې چاټۍ دې د ميو نه ډکې شى. او بيا دوئ جواب ور کړو چې، بې‌شکه، هره يوه چاټۍ به د ميو نه ډکه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18166, 'Jeremiah 13:13', 'Jeremiah', 13, 13, '&nbsp;نو بيا تۀ هغوئ ته ووايه چې، مالِک خُدائ فرمائى زۀ به د دې مُلک په ټولو خلقو او د داؤد په نسل، په بادشاهانو، او اِمامانو، پېغمبرانو دومره مے وڅښم چې ښۀ نشه شى او په هر هغه چا چې په يروشلم کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18167, 'Jeremiah 13:14', 'Jeremiah', 13, 14, '&nbsp;نو بيا به زۀ هغوئ په خپلو کښې سره وجنګومه تر دې چې مور پلار او بچى به په خپلو کښې يو بل زره زره کړى. او زۀ به په هغوئ هيڅ قسم رحم او ترس ونۀ کړم. او هيڅ څيز به ما د هغوئ د تباه کولو نه منع نۀ کړى.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18168, 'Jeremiah 13:15', 'Jeremiah', 13, 15, '&nbsp;په غور او احتياط سره واورئ او مغروره کېږئ مه. ځکه چې مالِک خُدائ دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18169, 'Jeremiah 13:16', 'Jeremiah', 13, 16, '&nbsp;د دې نه مخکښې چې ډېر ناوخته شى مالِک خُدائ، خپل خُدائ پاک ته جلال ورکړئ. او هغه وپېژنئ د دې نه وړاندې چې هغه درباندې تيارۀ راولى، او تاسو تيندک وخورئ او په تورو تيارو غرونو کښې راوغورزېږئ. او د هغه نُور چې تاسو يې په انتظار کښې يئ نو مالِک خُدائ به هغه په تورو تيارو بدل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18170, 'Jeremiah 13:17', 'Jeremiah', 13, 17, '&nbsp;کۀ تاسو اوس هم غوږ ونۀ نيسئ، نو زۀ به ستاسو د غرور په وجه پټ پټ وژاړم. زما سترګې به ترخه ژړا وکړى او ډکې به شى او اوښکې به ترې بهيږى. ځکه چې دشمن به د مالِک خُدائ قوم لکه د يوې رمې په شان راګېر کړى او قېدولو له به يې بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18171, 'Jeremiah 13:18', 'Jeremiah', 13, 18, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”بادشاه او د هغۀ مور ته ووايه چې، د تخت نه راکوز شه او په خاورو کښې کښېنه، ځکه چې ستا د شان او شوکت تاجونه به زر ستا د سر نه راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18172, 'Jeremiah 13:19', 'Jeremiah', 13, 19, '&nbsp;د نجب ښارونو دروازې به بند کړے شى او څوک به هم هغه نۀ شى کولاولے. د يهوداه ټول خلق به جلاوطن کړے شى او يو به هم بچ نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18173, 'Jeremiah 13:20', 'Jeremiah', 13, 20, '&nbsp;خپلې سترګې اوچتې کړه او هغه فوج وګوره چې د شمال د خوا نه راروان دے. ستا هغه ښکلې رَمې اوس چرته دى چې ما تا ته سپارلې وې؟ ستا هغه ګډان چرته دى چې تا به پرې فخر کولو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18174, 'Jeremiah 13:21', 'Jeremiah', 13, 21, '&nbsp;تۀ به په هغه ورځ څۀ وائې کله چې مالِک خُدائ په تا هغه خلق حکمرانان مقرر کړى کوم خلق چې تا خپله ډله جوړه کړې وه؟ لکه څنګه چې د ښځې د ماشوم د پېدا کېدو وخت وى نو تۀ به په دغه شان تکليف کښې شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18175, 'Jeremiah 13:22', 'Jeremiah', 13, 22, '&nbsp;کۀ تۀ چرې د خپل ځان نه تپوس وکړې چې دا هر څۀ ما سره ولې کيږى؟ نو دا ستا د ډېرو ګناهونو په وجه تا سره وشول. نو ځکه ستا نه جامې وويستلے شوې او هغه حمله کوونکو فوجيانو تا سره په زور زنا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18176, 'Jeremiah 13:23', 'Jeremiah', 13, 23, '&nbsp;ولې د ايتهوپيا يو سړے د خپلې څرمنې رنګ بدلولے شى؟ يا يو پړانګ د ځان نه خالونه لرې کولے شى څۀ؟ نه کله هم نه، هم دغه رنګ تۀ په بدو عملونو دومره عادت شوے يې چې تۀ کله هم نېک کارونه نۀ شې کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18177, 'Jeremiah 13:24', 'Jeremiah', 13, 24, '&nbsp;زۀ به تاسو لکه د بوسو په شان چې د صحرا هوا په مخه اخستې وى خوارۀ وارۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18178, 'Jeremiah 13:25', 'Jeremiah', 13, 25, '&nbsp;مالِک خُدائ فرمائى چې، دا ستا قسمت دے، هغه برخه چې ما ستا دپاره مقرر کړې ده. ځکه چې تا زۀ هېر کړے يم او په دروغژنو معبودانو دې يقين کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18179, 'Jeremiah 13:26', 'Jeremiah', 13, 26, '&nbsp;اے قومه، زۀ به په خپله ستاسو نه جامې وکاږم چې تاسو لغړ کړم او شرمګاه مو ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18180, 'Jeremiah 13:27', 'Jeremiah', 13, 27, '&nbsp;ما ستاسو زناکارى او د نفس خواهشات، ما ستاسو په بې‌شرمۍ سره د بُتانو عبادت په لوړو او ژورو باندې وليدلو. په تاسو دې افسوس وى، اے يروشلمه. ترڅو پورې به تاسو داسې حرام کاره او ناپاکه يئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18181, 'Jeremiah 14:1', 'Jeremiah', 14, 1, '&nbsp;د اوچ کالۍ په حقله په يرمياه د مالِک خُدائ کلام نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18182, 'Jeremiah 14:2', 'Jeremiah', 14, 2, '&nbsp;”يهوداه وير کوى، ښارونه يې لکه د اوچو شوو بوټو په شان غمژن دى، ټول خلق يې د غم په وجه په زمکه ناست دى او د يروشلم نه چغې او سورې راپورته کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18183, 'Jeremiah 14:3', 'Jeremiah', 14, 3, '&nbsp;مالداره خلق خپل نوکران د اوبو دپاره کُوهيانو ته لېږى، خو ټولې چينې کُوهيان اوچ شوى وى او د ګوټ اوبو درک هم نۀ لګى. نوکران په ډيرې مايوسۍ او خفګان د تشو منګو سره راواپس کيږى او خپل سرونه يې د پرېشانۍ په وجه پټ کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18184, 'Jeremiah 14:4', 'Jeremiah', 14, 4, '&nbsp;زمکه د خوشکۍ او د باران نۀ ورېدلو په وجه چاؤدلې ده، زميداران پرېشانه دى، او هغوئ هم خپل مخونه پټ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18185, 'Jeremiah 14:5', 'Jeremiah', 14, 5, '&nbsp;په پټو کښې د خوراک دپاره د ګياه د نشتوالى په وجه هوسۍ هم خپل تازه پېدا شوى بچى هم داسې په ډاګه پرېښى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18186, 'Jeremiah 14:6', 'Jeremiah', 14, 6, '&nbsp;ځنګلى خرونه هم د خوشکو غونډو په سرونو ودريږى او د ګيدړانو په شان چغې وهى او د خوراک د نشتوالى په وجه يې نظر کار پرېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18187, 'Jeremiah 14:7', 'Jeremiah', 14, 7, '&nbsp;زما خلق ما ته فرياد کوى او وائى چې، زمونږ ګناهونه زمونږ خِلاف ګواهى ورکوى، خو اے مالِکه خُدايه، د خپل نوم د خاطره دې زمونږ مدد وکړه. مونږ ستا نه په څو ځله اوړېدلى يُو، او ستا خِلاف مو ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18188, 'Jeremiah 14:8', 'Jeremiah', 14, 8, '&nbsp;اے مالِکه خُدايه صرف تۀ د بنى اِسرائيلو اُميد يې، او د تکليف په وخت کښې زمونږ خلاصونکے يې. نو بيا ولې تۀ لکه د يو مسافر په شان يې چې زمونږ په مُلک کښې صرف يوه شپه تېره کړى او بيا ځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18189, 'Jeremiah 14:9', 'Jeremiah', 14, 9, '&nbsp;تۀ ولې د هغه چا په شان يې چې ګنګس وى، او لکه د داسې فوجى په شان شوے يې چې څوک بچ کولے نۀ شى؟ اے مالِکه خُدايه، تۀ مونږ سره يې، او مونږ ستا نوم پورې تړلے شوى يُو، نو اوس مونږ مۀ پرېږده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18190, 'Jeremiah 14:10', 'Jeremiah', 14, 10, '&nbsp;نو مالِک خُدائ د دې خلقو په حقله فرمائى، ”د دوئ ډېر زيات دا خوښېدل چې فضول وګرځى او زما نه واوړى او په خپل ځان يې قابو نۀ وُو. نو ځکه زۀ د دوئ نه راضى نۀ يم. او د دوئ ګناهونه به راته ياد وى، او سزا به ورله ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18191, 'Jeremiah 14:11', 'Jeremiah', 14, 11, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”نور د دې قوم د خير دپاره ما ته سوال مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18192, 'Jeremiah 14:12', 'Jeremiah', 14, 12, '&nbsp;تر دې کۀ هغوئ روژه هم ونيسى، نو زۀ به د هغوئ فرياد ته غوږ نۀ نيسم. او کۀ چرې هغوئ ما ته سوزېدونکې او د غلې نذرانې هم پېش کړى، نو زۀ به هغه نۀ قبلوم. بلکې هغوئ به په جنګ، قحط او وبا باندې مړۀ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18193, 'Jeremiah 14:13', 'Jeremiah', 14, 13, '&nbsp;نو بيا ما ووئيل، ”اے قادر مطلق خُدايه، د هغوئ پېغمبران ورته وائى هر څۀ ټيک دى جنګ او قحط به نۀ راځى. مالِک خُدائ به په حقيقت کښې په تاسو امن راولېږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18194, 'Jeremiah 14:14', 'Jeremiah', 14, 14, '&nbsp;نو بيا مالِک خُدائ ما ته وفرمائيل چې، ”زما په نوم دا پېغمبران د دروغو نبوت کوى. د هغوئ پېغام زما له طرف نه نۀ دے او نۀ ما هغوئ ته حکم کړے دے چې تاسو دا پېغام خلقو له ورکړئ. هغوئ دروغژنې روياګانې، او فضول فالونه او د خپلو دروغژنو خيالونو پېشګويانې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18195, 'Jeremiah 14:15', 'Jeremiah', 14, 15, '&nbsp;نو ځکه مالِک خُدائ فرمائى چې کوم پېغمبران چې زما په نوم د دروغو نبوت کوى او خلقو ته وائى چې نۀ به جنګ راځى او نۀ به قحط، چا ته چې ما پېغام نۀ دے ورکړے نو هم دوئ به زۀ په جنګ او قحط باندې هلاک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18196, 'Jeremiah 14:16', 'Jeremiah', 14, 16, '&nbsp;کومو خلقو ته چې هغوئ دا پېشګويانې کوى نو د هغوئ لاشونه به د يروشلم په لارو کوڅو کښې د جنګ او قحط په وجه وغورزولے شى. څوک به نۀ وى چې هغوئ او د هغوئ ښځې، زامن، لوڼه ښخ کړى. او زۀ به په هغوئ هغه افت نازل کړم د کوم چې لائق دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18197, 'Jeremiah 14:17', 'Jeremiah', 14, 17, '&nbsp;مالِک خُدائ ما ته وفرمائيل چې، ”يرمياه هغوئ ته دا ووايه، زما د سترګو نه شپه او ورځ اوښکې بهيږى، زما ژړا نۀ ودريږى، ځکه چې زما قوم چې په ما لکه د لور په شان ګران دے سخت زخمى شوے دے او زيات ژوبل شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18198, 'Jeremiah 14:18', 'Jeremiah', 14, 18, '&nbsp;کله چې زۀ بهر مېدانونو ته لاړ شم، نو زۀ هغوئ وينم څوک چې په جنګ کښې په تُورو مړۀ شوى دى، او کۀ زۀ دننه د ښار کوڅو ته لاړ شم، نو زۀ هغه خلق ګورم چې د قحط په وجه مړۀ شوى دى. پېغمبران او اِمامان دواړه خپل کارونه جارى ساتى، خو هغوئ په دې نۀ پوهيږى چې څۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18199, 'Jeremiah 14:19', 'Jeremiah', 14, 19, '&nbsp;اے مالِکه خُدايه، تا يهوداه بلکل رد کړے دے څۀ؟ آيا تۀ د صيون د خلقو نه نفرت کوې څۀ؟ ولې تا مونږ دومره سخت زخمى کړى يُو چې د رغېدو ټول اُميدونه مو ختم شُو څۀ؟ مونږ د خير اُميد لرلو خو مونږ ته خير مِلاو نۀ شو، مونږ د علاج په طمع وُو خو د شفا په ځائ په مونږ يره راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18200, 'Jeremiah 14:20', 'Jeremiah', 14, 20, '&nbsp;اے مالِکه خُدايه، مونږ ستا خِلاف بدکارونه کړى دى، مونږ د خپلو بدو کارونو او د خپل پلار نيکۀ د بدو کارونو اِقرار کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');